using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    private static int ChargedCents(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Returning Bronze customer is charged the Bronze price for a basket
    [Theory]
    [InlineData(10000, 9500)]
    [InlineData(7, 7)]
    public void S1_BronzeCustomerIsChargedTheBronzePrice(int subtotalCents, int chargedCents) =>
        Assert.Equal(chargedCents, ChargedCents(LoyaltyTier.Bronze, subtotalCents));

    // Returning Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverCustomerIsChargedTheSilverPrice() =>
        Assert.Equal(9000, ChargedCents(LoyaltyTier.Silver, 10000));

    // Returning Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldCustomerIsChargedTheGoldPrice() =>
        Assert.Equal(8500, ChargedCents(LoyaltyTier.Gold, 10000));
}

